import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int totalItems = input.nextInt();
        int capacity = input.nextInt();
        int[] data = new int[totalItems];
        for (int i = 0; i < totalItems; i++) {
            data[i] = input.nextInt();
        }
        int evenCounter = 0, oddCounter = 0;
        PriorityQueue<Integer> diffQueue = new PriorityQueue<>();
        for (int i = 0; i < totalItems; i++) {
            if (data[i] % 2 == 0) {
                evenCounter++;
            } else {
                oddCounter++;
            }
            if (evenCounter == oddCounter && i < totalItems - 1) {
                diffQueue.add(Math.abs(data[i + 1] - data[i]));
            }
        }
        int totalCost = 0, pairs = 0;
        while (!diffQueue.isEmpty() && totalCost + diffQueue.peek() <= capacity) {
            totalCost += diffQueue.poll();
            pairs++;
        }
        System.out.println(pairs);
    }
}
