#include <iostream>
#include <vector>
#include <queue>
#include <cmath>

int main() {
    int totalItems, capacity;
    std::cin >> totalItems >> capacity;
    std::vector<int> data(totalItems);
    for (int i = 0; i < totalItems; ++i) {
        std::cin >> data[i];
    }
    int evenCounter = 0, oddCounter = 0;
    std::priority_queue<int, std::vector<int>, std::greater<int>> diffQueue;
    for (int i = 0; i < totalItems; ++i) {
        if (data[i] % 2 == 0) {
            ++evenCounter;
        } else {
            ++oddCounter;
        }
        if (evenCounter == oddCounter && i < totalItems - 1) {
            diffQueue.push(std::abs(data[i + 1] - data[i]));
        }
    }
    int totalCost = 0, pairs = 0;
    while (!diffQueue.empty() && totalCost + diffQueue.top() <= capacity) {
        totalCost += diffQueue.top();
        diffQueue.pop();
        ++pairs;
    }
    std::cout << pairs << std::endl;
    return 0;
}
